                  className="zcc-wl-input"
                  type="email"
                  placeholder="Enter email to join waitlist"
                  readOnly
                />
                <button className="zcc-wl-btn" type="button">
                  Join Waitlist
                </button>
              </div>
            )}
        </div>
      )}
    </div>
  );

  // Floating position: show mock fixed button + collapsible panel concept
  if (cfg.position === "floating") {
    return (
      <>
        {/* eslint-disable-next-line react/no-danger */}
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <div
          style={{
            position: "relative",
            minHeight: "120px",
            background: "#f6f6f7",
            borderRadius: "8px",
            padding: "12px",
          }}
        >
          <Text as="p" variant="bodySm" tone="subdued">
            The widget will appear as a fixed button in the bottom-right corner of your storefront.
          </Text>
          <div
            style={{
              position: "absolute",
              bottom: "12px",
              right: "12px",
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-end",
              gap: "8px",
            }}
          >
            <div id={wid} style={{ maxWidth: "300px" }}>
              <p className="zcc-heading" style={{ marginBottom: "12px" }}>
                {cfg.heading}
              </p>
              <div className="zcc-row">
                <input
                  className="zcc-input"
                  type="text"
                  placeholder={cfg.placeholder}
                  readOnly
                />
                <button className="zcc-btn" type="button">
                  {cfg.buttonText}
                </button>
              </div>
            </div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: "50px",
                padding: "10px 18px",
                fontSize: "13px",
                fontWeight: 600,
                cursor: "pointer",
                boxShadow: "0 4px 12px rgba(0,0,0,.2)",
              }}
            >
              📍 Check Delivery
            </button>
          </div>
        </div>
      </>
    );
  }

  // Popup position: show trigger button + hint of overlay
  if (cfg.position === "popup") {
    return (
      <>
        {/* eslint-disable-next-line react/no-danger */}
        <style dangerouslySetInnerHTML={{ __html: css }} />
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          <Text as="p" variant="bodySm" tone="subdued">
            A trigger button will appear in the section. Clicking it opens a centered popup.
          </Text>
          <div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: cfg.borderRadius + "px",
                padding: "10px 24px",
                fontSize: "14px",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              Check Delivery Availability
            </button>
          </div>
          <div
            style={{
              background: "rgba(0,0,0,.06)",
              borderRadius: "8px",
              padding: "12px",
              border: "2px dashed #c9cccf",
            }}
          >
            <Text as="p" variant="bodySm" tone="subdued">
              Popup content preview:
            </Text>
            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
          </div>
        </div>
      </>
    );
  }

  // Inline (default)
  return (
    <>
      {/* eslint-disable-next-line react/no-danger */}
      <style dangerouslySetInnerHTML={{ __html: css }} />
      {widgetHtml}
    </>
  );
}

// ── Page component ───────────────────────────────────────────────────────────
