    setResetModalOpen(false);
    shopify.toast.show("Widget settings reset to defaults");
  }, [fetcher, shopify]);

  const positionOptions = [
    { label: "Inline — embedded directly in the section", value: "inline" },
    { label: "Floating — fixed button in the corner", value: "floating" },
    { label: "Popup — trigger button opens a modal", value: "popup" },
  ];

  // Current config snapshot for the preview
  const previewCfg: WidgetConfig = {
    position, primaryColor, successColor, errorColor, backgroundColor,
    textColor, heading, placeholder, buttonText, successMessage, errorMessage,
    notFoundMessage, showEta, showZone, showWaitlistOnFailure, showCod,
    showReturnPolicy, showCutoffTime, showDeliveryDays, blockCartOnInvalid,
    blockCheckoutInCart, showSocialProof, borderRadius, customCss,
  };

  const handleDiscard = useCallback(() => {
    setPosition(c.position);
    setPrimaryColor(c.primaryColor);
    setSuccessColor(c.successColor);
    setErrorColor(c.errorColor);
    setBackgroundColor(c.backgroundColor);
    setTextColor(c.textColor);
    setHeading(c.heading);
    setPlaceholder(c.placeholder);
    setButtonText(c.buttonText);
    setSuccessMessage(c.successMessage);
    setErrorMessage(c.errorMessage);
    setNotFoundMessage(c.notFoundMessage);
    setShowEta(c.showEta);
    setShowZone(c.showZone);
    setShowWaitlistOnFailure(c.showWaitlistOnFailure);
    setShowCod(c.showCod ?? true);
    setShowReturnPolicy(c.showReturnPolicy ?? true);
    setShowCutoffTime(c.showCutoffTime ?? true);
    setShowDeliveryDays(c.showDeliveryDays ?? true);
    setBlockCartOnInvalid(c.blockCartOnInvalid ?? false);
    setBlockCheckoutInCart(c.blockCheckoutInCart ?? false);
    setShowSocialProof(c.showSocialProof ?? true);
    setBorderRadius(c.borderRadius);
    setCustomCss(c.customCss || "");
    setIsDirty(false);
    setPreviewState("idle");
  }, [c]);

  return (
    <Page
      title="Widget Customization"
      subtitle="Customize how the zip code checker looks on your storefront"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={isDirty ? {
        content: "Save Changes",
        onAction: handleSave,
        loading: isSaving,
      } : undefined}
      secondaryActions={[
        ...(isDirty ? [{
          content: "Discard",
          onAction: handleDiscard,
        }] : []),
        {
          content: "Reset to Defaults",
          onAction: () => setResetModalOpen(true),
        },
      ]}
    >
      <Box paddingBlockEnd="1600">
        <Layout>

          {/* Settings + Preview */}
          <Layout.Section>
            <InlineGrid columns={{ xs: 1, md: 2 }} gap="400" alignItems="start">
              {/* ── Settings Column ── */}
              <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="h2" variant="headingMd">
                        Layout
                      </Text>
                      {!limits.widgetFullCustom && (
                        <Badge tone="info">Starter+</Badge>
                      )}
                    </InlineStack>
                    <Select
                      label="Widget Position"
                      options={positionOptions}
                      value={position}
                      onChange={handlePositionChange}
                      disabled={!limits.widgetFullCustom}
                      helpText={
                        position === "floating"
                          ? "Widget appears as a fixed button in the bottom-right corner of every page."
                          : position === "popup"
                          ? "A trigger button shows in the block. Clicking it opens a centered popup overlay."
                          : "Widget renders directly where you place the block in the Theme Editor."
                      }
                    />
                    <TextField
                      label="Border Radius (px)"
                      type="number"
                      value={borderRadius}
                      onChange={handleBorderRadiusChange}
                      autoComplete="off"
                      disabled={!limits.widgetFullCustom}
                      helpText="Roundness of corners. 0 = square, 16 = very rounded."
                    />
                    {!limits.widgetFullCustom && (
                      <Banner tone="info">
                        <Text as="p" variant="bodySm">
                          Upgrade to Starter to customize widget position and layout.{" "}
                          <Button
                            variant="plain"
                            onClick={() => navigate("/app/pricing")}
                          >
                            View plans
                          </Button>
                        </Text>
                      </Banner>
                    )}
                  </BlockStack>
                </Card>

                {/* Colors */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="h2" variant="headingMd">
                        Colors
                      </Text>
                      {!limits.widgetFullCustom && (
                        <Badge tone="info">Starter+</Badge>
                      )}
                    </InlineStack>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Button Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={primaryColor}
                              onChange={(e) => handlePrimaryColorChange(e.target.value)}
                              disabled={!limits.widgetFullCustom}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                                padding: "2px",
                                opacity: limits.widgetFullCustom ? 1 : 0.5,
                              }}
                            />
                            <TextField
                              label="Button"
                              labelHidden
                              value={primaryColor}
                              onChange={handlePrimaryColorChange}
                              autoComplete="off"
                              disabled={!limits.widgetFullCustom}
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Success Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={successColor}
                              onChange={(e) => handleSuccessColorChange(e.target.value)}
                              disabled={!limits.widgetFullCustom}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                                padding: "2px",
                                opacity: limits.widgetFullCustom ? 1 : 0.5,
                              }}
                            />
                            <TextField
                              label="Success"
                              labelHidden
                              value={successColor}
                              onChange={handleSuccessColorChange}
                              autoComplete="off"
                              disabled={!limits.widgetFullCustom}
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Error Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={errorColor}
                              onChange={(e) => handleErrorColorChange(e.target.value)}
                              disabled={!limits.widgetFullCustom}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                                padding: "2px",
                                opacity: limits.widgetFullCustom ? 1 : 0.5,
                              }}
                            />
                            <TextField
                              label="Error"
                              labelHidden
                              value={errorColor}
                              onChange={handleErrorColorChange}
                              autoComplete="off"
                              disabled={!limits.widgetFullCustom}
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Background
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={backgroundColor}
                              onChange={(e) => handleBackgroundColorChange(e.target.value)}
                              disabled={!limits.widgetFullCustom}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                                padding: "2px",
                                opacity: limits.widgetFullCustom ? 1 : 0.5,
                              }}
                            />
                            <TextField
                              label="BG"
                              labelHidden
                              value={backgroundColor}
                              onChange={handleBackgroundColorChange}
                              autoComplete="off"
                              disabled={!limits.widgetFullCustom}
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodySm">
                        Text Color
                      </Text>
                      <InlineStack gap="200" blockAlign="center">
                        <input
                          type="color"
                          value={textColor}
                          onChange={(e) => handleTextColorChange(e.target.value)}
                          disabled={!limits.widgetFullCustom}
                          style={{
                            width: "36px",
                            height: "36px",
                            border: "1px solid #ccc",
                            borderRadius: "6px",
                            cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                            padding: "2px",
                            opacity: limits.widgetFullCustom ? 1 : 0.5,
                          }}
                        />
                        <TextField
                          label="Text"
                          labelHidden
                          value={textColor}
                          onChange={handleTextColorChange}
                          autoComplete="off"
                          disabled={!limits.widgetFullCustom}
                        />
                      </InlineStack>
                    </BlockStack>
                    {!limits.widgetFullCustom && (
                      <Banner tone="info">
                        <Text as="p" variant="bodySm">
                          Upgrade to Starter to customize widget colors.{" "}
                          <Button
                            variant="plain"
                            onClick={() => navigate("/app/pricing")}
                          >
                            View plans
                          </Button>
                        </Text>
                      </Banner>
                    )}
                  </BlockStack>
                </Card>

                {/* Text Content */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Text Content
                    </Text>
                    <TextField
                      label="Heading"
                      value={heading}
                      onChange={handleHeadingChange}
                      autoComplete="off"
                    />
                    <InlineStack gap="300">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Placeholder"
                          value={placeholder}
                          onChange={handlePlaceholderChange}
                          autoComplete="off"
                        />
                      </div>
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Button Text"
                          value={buttonText}
                          onChange={handleButtonTextChange}
                          autoComplete="off"
                        />
                      </div>
                    </InlineStack>
                    <TextField
                      label="Success Message"
                      value={successMessage}
                      onChange={handleSuccessMessageChange}
                      autoComplete="off"
                      multiline={2}
                    />
                    <TextField
                      label="Error Message (blocked)"
                      value={errorMessage}
                      onChange={handleErrorMessageChange}
                      autoComplete="off"
                      multiline={2}
                    />
                    <TextField
                      label="Not Found Message"
                      value={notFoundMessage}
                      onChange={handleNotFoundMessageChange}
                      autoComplete="off"
                      multiline={2}
                    />
                  </BlockStack>
                </Card>

                {/* Display Options */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="h2" variant="headingMd">
                        Display Options
                      </Text>
                      {!limits.showEtaCodReturn && (
                        <Badge tone="info">Starter+</Badge>
                      )}
                    </InlineStack>
                    <Checkbox
                      label="Show estimated delivery time (ETA)"
                      checked={showEta}
                      onChange={handleShowEtaChange}
                      disabled={!limits.showEtaCodReturn}
                      helpText="Display the ETA below the success message when available."
                    />
                    <Checkbox
                      label="Show delivery zone name"
                      checked={showZone}
                      onChange={handleShowZoneChange}
                      helpText="Display the zone name in the success message."
                    />
                    <Checkbox
                      label="Show waitlist form on blocked/not-found zip codes"
                      checked={showWaitlistOnFailure}
                      onChange={handleShowWaitlistChange}
                      helpText="Let customers enter their email to join a waitlist when their zip code isn't available."
                    />
                    <Checkbox
                      label="Show cutoff time"
                      checked={showCutoffTime}
                      onChange={handleShowCutoffTimeChange}
                      helpText="Display order cutoff time for same-day delivery (from the matched delivery rule)."
                    />
                    <Checkbox
                      label="Show delivery days"
                      checked={showDeliveryDays}
                      onChange={handleShowDeliveryDaysChange}
                      helpText="Display which days of the week delivery is available (from the matched delivery rule)."
                    />
                    <Checkbox
                      label="Show COD (Cash on Delivery) availability"
                      checked={showCod}
                      onChange={handleShowCodChange}
                      disabled={!limits.showEtaCodReturn}
                      helpText="Display whether cash on delivery is available for the entered zip code."
                    />
                    <Checkbox
                      label="Show return / exchange policy"
                      checked={showReturnPolicy}
                      onChange={handleShowReturnPolicyChange}
                      disabled={!limits.showEtaCodReturn}
                      helpText="Display the return and exchange policy associated with the entered zip code."
                    />
                    {!limits.showEtaCodReturn && (
                      <Banner tone="info">
                        <Text as="p" variant="bodySm">
                          Upgrade to Starter to enable ETA, COD, and return policy toggles.{" "}
                          <Button
                            variant="plain"
                            onClick={() => navigate("/app/pricing")}
                          >
                            View plans
                          </Button>
                        </Text>
                      </Banner>
                    )}
                    <Divider />
                    <InlineStack align="space-between" blockAlign="center">
                      <Text variant="headingMd" as="h3">Purchase Protection</Text>
                      {!limits.cartBlocking && (
                        <Badge tone="info">Pro+</Badge>
                      )}
                    </InlineStack>
                    <Checkbox
                      label="Block Add to Cart for unserviceable ZIP codes"
                      helpText="Disables the Add to Cart and Buy Now buttons when a customer enters an invalid ZIP code. Buttons re-enable on a valid check."
                      checked={blockCartOnInvalid}
                      onChange={handleBlockCartOnInvalidChange}
                      disabled={!limits.cartBlocking}
                    />
                    <Checkbox
                      label="Block checkout in cart for unserviceable ZIP codes"
                      helpText="Shows a warning and hides the checkout button on the cart page if the last checked ZIP was unserviceable. Requires the Cart Validator block on your cart page."
                      checked={blockCheckoutInCart}
                      onChange={handleBlockCheckoutInCartChange}
                      disabled={!limits.cartBlocking}
                    />
                    {!limits.cartBlocking && (
                      <Banner tone="info">
                        <Text as="p" variant="bodySm">
                          Upgrade to Pro to enable cart and checkout blocking for unserviceable ZIP codes.{" "}
                          <Button
                            variant="plain"
                            onClick={() => navigate("/app/pricing")}
                          >
                            View plans
                          </Button>
                        </Text>
                      </Banner>
                    )}
                    <Divider />
                    <Text variant="headingMd" as="h3">Waitlist Engagement</Text>
                    <Checkbox
                      label="Show social proof on waitlist form"
                      helpText="Displays how many other customers are waiting for delivery to the same ZIP code. Example: 'Join 23 others waiting for delivery to your area.'"
                      checked={showSocialProof}
                      onChange={handleShowSocialProofChange}
                    />
                  </BlockStack>
                </Card>

                {/* Custom CSS */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="h2" variant="headingMd">
                        Custom CSS
                      </Text>
                      {!limits.customCss && (
                        <Badge tone="info">Ultimate</Badge>
                      )}
                    </InlineStack>
                    <TextField
                      label="Custom CSS"
                      labelHidden
                      value={customCss}
                      onChange={handleCustomCssChange}
                      multiline={4}
                      placeholder=".zcc-heading { font-size: 18px; } .zcc-btn { border-radius: 4px; }"
                      autoComplete="off"
                      disabled={!limits.customCss}
                      helpText="Target .zcc-heading, .zcc-btn, .zcc-input, .zcc-result, .zcc-meta classes."
                    />
                    {!limits.customCss && (
                      <Banner tone="info">
                        <Text as="p" variant="bodySm">
                          Upgrade to Ultimate to add custom CSS overrides.{" "}
                          <Button
                            variant="plain"
                            onClick={() => navigate("/app/pricing")}
                          >
                            View plans
                          </Button>
                        </Text>
                      </Banner>
                    )}
                  </BlockStack>
                </Card>
              </BlockStack>

              {/* ── Live Preview Column ── */}
              <div style={{ position: "sticky", top: "16px", alignSelf: "start" }}>
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Live Preview
                    </Text>
                    <Divider />

                    {/* Preview toggle buttons */}
                    <InlineStack gap="200" wrap>
                      <Button
                        size="slim"
                        pressed={previewState === "idle"}
                        onClick={() => setPreviewState("idle")}
                      >
                        Default
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "success"}
                        onClick={() => setPreviewState("success")}
                      >
                        Success
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "error"}
                        onClick={() => setPreviewState("error")}
                      >
                        Blocked
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "notfound"}
                        onClick={() => setPreviewState("notfound")}
                      >
                        Not Found
                      </Button>
                    </InlineStack>

                    {/* Preview widget */}
                    <Box
                      padding="400"
                      background="bg-surface-secondary"
                      borderRadius="200"
                    >
                      <WidgetPreview cfg={previewCfg} previewState={previewState} />
                    </Box>

                    <Text as="p" tone="subdued" variant="bodySm">
                      Preview reflects all current settings including custom CSS.
                      Click state buttons above to see different scenarios.
                    </Text>
                  </BlockStack>
                </Card>
              </div>
            </InlineGrid>
          </Layout.Section>
        </Layout>
      </Box>
      {/* Reset Confirmation Modal */}
      <Modal
        open={resetModalOpen}
        onClose={() => setResetModalOpen(false)}
        title="Reset to default settings?"
        primaryAction={{
          content: "Reset to Defaults",
          onAction: handleResetConfirm,
          destructive: true,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setResetModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <Text as="p" variant="bodyMd">
            This will erase all your current widget customizations (colors,
            messages, toggles, custom CSS) and restore the original default
            settings. This action cannot be undone.
          </Text>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

content.content:
  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% if request.design_mode %}
  8→  {% comment %}
  9→    Theme Editor preview — shows two states:
 10→    1. If app embed is active → full widget preview
 11→    2. If app embed is NOT active → "Enable app embed" placeholder
 12→    We check window.__zccAppEnabled which is set by the app embed block.
 13→  {% endcomment %}
 14→  <div id="zcc-editor-{{ block.id }}">
 15→    <!-- Inactive state (shown by default) -->
 16→    <div id="zcc-inactive-{{ block.id }}" style="
 17→      background:#f6f6f7;border:1px dashed #c9cccf;border-radius:8px;
 18→      padding:20px;max-width:480px;text-align:center;
 19→      font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 20→      color:#6d7175;font-size:13px;box-sizing:border-box;
 21→    ">
 22→      <p style="margin:0 0 6px;font-weight:600;color:#202223;font-size:15px;">Zip Code Checker</p>
 23→      <p style="margin:0 0 4px;">This widget requires the app embed to be enabled.</p>
 24→      <p style="margin:0;font-size:12px;">Go to <strong>App Embeds</strong> and toggle on <strong>Zip Code Checker</strong> to activate.</p>
 25→    </div>
 26→    <!-- Active preview (hidden by default) -->
 27→    <div id="zcc-active-{{ block.id }}" style="display:none;">
 28→      <div style="
 29→        background:#ffffff;
 30→        border:1px solid #e1e3e5;
 31→        border-radius:8px;
 32→        padding:24px;
 33→        max-width:480px;
 34→        font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 35→        box-sizing:border-box;
 36→        color:#202223;
 37→      ">
 38→        <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
 39→        <div style="display:flex;gap:8px;margin-bottom:12px;">
 40→          <input type="text" placeholder="Enter your zip code" disabled style="
 41→            flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
 42→            font-size:14px;background:#fafbfb;color:#202223;min-width:0;
 43→          ">
 44→          <button type="button" disabled style="
 45→            background:#008060;color:#fff;border:none;border-radius:8px;
 46→            padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
 47→            opacity:0.7;cursor:default;
 48→          ">Check</button>
 49→        </div>
 50→        <div style="
 51→          background:#00806015;border-left:3px solid #008060;border-radius:8px;
 52→          padding:12px;font-size:14px;color:#008060;line-height:1.4;
 53→        ">
 54→          Great news! We deliver to your area.
 55→          <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
 56→        </div>
 57→        <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
 58→          Zip Code Checker — live widget loads on your storefront
 59→        </p>
 60→      </div>
 61→    </div>
 62→  </div>
 63→  <script>
 64→  (function() {
 65→    var bid = "{{ block.id }}";
 66→    function check() {
 67→      if (window.__zccAppEnabled) {
 68→        var inactive = document.getElementById('zcc-inactive-' + bid);
 69→        var active = document.getElementById('zcc-active-' + bid);
 70→        if (inactive) inactive.style.display = 'none';
 71→        if (active) active.style.display = 'block';
 72→      }
 73→    }
 74→    check();
 75→    setTimeout(check, 500);
 76→    setTimeout(check, 1500);
 77→    setTimeout(check, 3000);
 78→  })();
 79→  </script>
 80→{% else %}
 81→
 82→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
 83→
 84→<div
 85→  id="zcc-widget-{{ block.id }}"
 86→  data-zcc-widget="true"
 87→  data-shop="{{ shop.permanent_domain }}"
 88→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 89→  data-block="{{ block.id }}"
 90→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 91→  {{ block.shopify_attributes }}
 92→></div>
 93→
 94→<script>
 95→(function () {
 96→  // Wait for app embed to set window.__zccAppEnabled.
 97→  // App embed (target: body) may load after this section block, so we poll briefly.
 98→  var maxWait = 3000; // ms
 99→  var interval = 50;  // ms
100→  var elapsed = 0;
101→
102→  function tryInit() {
103→    if (window.__zccAppEnabled) {
104→      init();
105→    } else if (elapsed < maxWait) {
106→      elapsed += interval;
107→      setTimeout(tryInit, interval);
108→    }
109→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
110→  }
111→
112→  // Start checking — if already set, runs immediately
113→  if (document.readyState === 'loading') {
114→    document.addEventListener('DOMContentLoaded', tryInit);
115→  } else {
116→    tryInit();
117→  }
118→
119→  function init() {
120→  var ROOT_ID = "zcc-widget-{{ block.id }}";
121→  var container = document.getElementById(ROOT_ID);
122→  if (!container) return;
123→
124→  var SHOP = container.dataset.shop;
125→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
126→
127→  // Try embedded config from metafield first (instant, no network needed)
128→  var configStr = container.getAttribute("data-config");
