535→        } else {
536→          wBtn.disabled = false;
537→          wBtn.textContent = "Submit Request";
538→        }
539→      })
540→      .catch(function () {
541→        wBtn.disabled = false;
542→        wBtn.textContent = "Submit Request";
543→      });
544→  }
