601→        '</div>' +
602→      '</div>' +
603→      '<button id="' + WID + '-trigger" type="button">' +
604→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
605→        esc(cfg.buttonText || "Check Delivery") +
606→      '</button>';
607→
608→    document.body.appendChild(floatEl);
609→
610→    // Wire toggle
611→    var trigger = document.getElementById(WID + "-trigger");
612→    var panel = document.getElementById(WID + "-panel");
613→    var closeBtn = document.getElementById(WID + "-close");
614→
615→    if (trigger && panel) {
616→      trigger.addEventListener("click", function () {
617→        panel.classList.toggle("zcc-hidden");
618→      });
619→    }
620→    if (closeBtn && panel) {
621→      closeBtn.addEventListener("click", function () {
622→        panel.classList.add("zcc-hidden");
623→      });
624→    }
625→    // Close on outside click
626→    document.addEventListener("click", function (e) {
627→      if (!floatEl.contains(e.target)) {
628→        if (panel) panel.classList.add("zcc-hidden");
629→      }
630→    });
631→
632→    wireWidget(WID, cfg, API_BASE, SHOP);
633→  }
634→
635→  // ── Popup position ───────────────────────────────────────────────────────────
636→  function renderPopup(cfg, WID, rad) {
637→    injectCss(WID, cfg, rad);
638→
639→    var popupCss =
640→      "#" + WID + "-overlay{" +
641→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
642→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
643→      "}" +
644→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
645→      "#" + WID + "-modal{" +
646→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
647→        "max-width:480px !important;width:100% !important;position:relative !important;" +
648→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
649→      "}" +
650→      "#" + WID + "-modal .zcc-modal-close{" +
651→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
652→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
653→      "}" +
654→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
655→      "#" + WID + "-popup-trigger{" +
656→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
657→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
658→        "cursor:pointer !important" +
659→      "}" +
660→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
661→
662→    var popupStyle = document.createElement("style");
663→    popupStyle.textContent = popupCss;
664→    document.head.appendChild(popupStyle);
665→
666→    // Trigger button renders in-place (inside the block)
667→    container.innerHTML =
668→      '<button id="' + WID + '-popup-trigger" type="button">' +
669→        esc(cfg.heading) +
670→      '</button>';
671→
672→    // Overlay + modal append to body
673→    var overlay = document.createElement("div");
674→    overlay.id = WID + "-overlay";
675→    overlay.innerHTML =
676→      '<div id="' + WID + '-modal">' +
677→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
678→        '<div id="' + WID + '" data-zcc-widget="true">' +
679→          buildWidgetInner(WID, cfg, cfg.buttonText) +
680→        '</div>' +
681→      '</div>';
682→    document.body.appendChild(overlay);
683→
684→    var trigger = document.getElementById(WID + "-popup-trigger");
685→    var closeBtn = document.getElementById(WID + "-modal-close");
686→    var modal = document.getElementById(WID + "-modal");
687→
688→    function openPopup() { overlay.classList.add("zcc-open"); }
689→    function closePopup() { overlay.classList.remove("zcc-open"); }
690→
691→    if (trigger) trigger.addEventListener("click", openPopup);
692→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
693→
694→    // Close on overlay backdrop click (not modal content)
695→    overlay.addEventListener("click", function (e) {
696→      if (e.target === overlay) closePopup();
697→    });
698→
699→    // Close on Escape key
700→    document.addEventListener("keydown", function (e) {
701→      if (e.key === "Escape") closePopup();
702→    });
703→
704→    wireWidget(WID, cfg, API_BASE, SHOP);
705→  }
706→
707→  function esc(str) {
708→    return String(str)
709→      .replace(/&/g, "&amp;")
710→      .replace(/</g, "&lt;")
711→      .replace(/>/g, "&gt;")
712→      .replace(/"/g, "&quot;");
713→  }
714→
715→  function escAttr(str) {
716→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
717→  }
718→  } // end init()
719→})();
720→</script>
721→
722→{% endif %}
